package vn.edu.fpt.seal.modules.participant.repository; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.stereotype.Repository; import vn.edu.fpt.seal.common.enums.RoundParticipantStatus; import vn.edu.fpt.seal.modules.participant.entity.RoundParticipant; import java.util.*;
@Repository public interface RoundParticipantRepository extends JpaRepository<RoundParticipant,UUID>{ @EntityGraph(attributePaths={"round","team"}) Page<RoundParticipant> findByRoundId(UUID roundId,Pageable p); @EntityGraph(attributePaths={"round","team"}) Page<RoundParticipant> findByTeamId(UUID teamId,Pageable p); @EntityGraph(attributePaths={"round","team"}) Page<RoundParticipant> findByStatus(RoundParticipantStatus status,Pageable p); boolean existsByRoundIdAndTeamId(UUID roundId,UUID teamId); boolean existsByRoundId(UUID roundId); boolean existsByRoundLogicalRoundIdAndTeamId(UUID logicalRoundId,UUID teamId); boolean existsByTeamId(UUID teamId); long countByRoundId(UUID roundId); @EntityGraph(attributePaths={"round","team"}) Optional<RoundParticipant> findWithRelationsById(UUID id); }
